
.mall-panel {
  display: flex;
  flex-direction: column;
  gap: 14px;
}

.inventory-section,
.catalog-section {
  display: flex;
  flex-direction: column;
  gap: 9px;
}

.sec-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  flex-wrap: wrap;
  gap: 8px;
  padding-bottom: 6px;
  border-bottom: 1px dashed var(--c-border);
}

.sec-title {
  display: flex;
  align-items: center;
  gap: 6px;
  font-size: 0.86rem;
  font-weight: 700;
  color: #ff8fb8;
}

.balance-tag {
  font-size: 0.76rem;
  color: var(--c-text-secondary);
}

.balance-tag strong {
  color: var(--c-primary);
  font-family: var(--font-mono);
}

.sec-hint {
  font-size: 0.7rem;
  color: var(--c-text-muted);
}

.inv-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(240px, 1fr));
  gap: 8px;
}

.inv-card {
  background: var(--c-surface-card);
  border: 1px solid var(--c-border);
  border-radius: 8px;
  padding: 8px 10px;
  display: flex;
  flex-direction: column;
  gap: 5px;
}

.inv-top {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 6px;
}

.inv-name-wrap {
  display: flex;
  align-items: center;
  gap: 6px;
  flex-wrap: wrap;
}

.inv-cat-tag {
  font-size: 0.65rem;
  padding: 1px 5px;
  border-radius: 4px;
  background: var(--c-spirit-soft);
  color: #d4b8ff;
}

.inv-name {
  font-size: 0.84rem;
  font-weight: 700;
  color: var(--c-text-primary);
}

.inv-actions {
  display: flex;
  align-items: center;
  gap: 6px;
}

.inv-qty {
  font-family: var(--font-mono);
  font-size: 0.78rem;
  font-weight: 700;
  color: var(--c-accent-gold);
}

.use-btn {
  padding: 2px 7px;
  font-size: 0.68rem;
  border-radius: 4px;
  border: 1px solid var(--c-border);
  background: var(--c-primary-soft);
  color: #ff9ec2;
  cursor: pointer;
}

.use-btn:hover {
  background: var(--c-primary);
  color: #fff;
}

.inv-desc {
  font-size: 0.74rem;
  color: var(--c-text-secondary);
  line-height: 1.38;
}

.empty-inv {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  padding: 12px;
  border-radius: 8px;
  background: rgba(14, 9, 22, 0.5);
  border: 1px dashed var(--c-border-subtle);
  font-size: 0.77rem;
  color: var(--c-text-muted);
}

.category-tabs {
  display: flex;
  flex-wrap: wrap;
  gap: 5px;
}

.cat-chip {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  padding: 4px 9px;
  border-radius: 6px;
  border: 1px solid var(--c-border-subtle);
  background: var(--c-surface-card);
  color: var(--c-text-secondary);
  font-size: 0.72rem;
  font-weight: 600;
  cursor: pointer;
  transition: all 0.15s ease;
}

.cat-chip:hover {
  border-color: var(--c-border);
  color: var(--c-text-primary);
}

.cat-chip.active {
  background: var(--c-primary-soft);
  border-color: var(--c-primary);
  color: #fff;
}

.catalog-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(215px, 1fr));
  gap: 8px;
}

.good-card {
  background: rgba(20, 14, 28, 0.85);
  border: 1px solid var(--c-border-subtle);
  border-radius: 8px;
  padding: 9px 11px;
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  gap: 6px;
}

.good-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 6px;
}

.good-name {
  font-size: 0.83rem;
  font-weight: 700;
  color: var(--c-text-primary);
}

.good-price {
  font-family: var(--font-mono);
  font-size: 0.72rem;
  font-weight: 700;
  color: var(--c-accent-gold);
  background: var(--c-accent-gold-soft);
  padding: 1px 6px;
  border-radius: 4px;
}

.good-effect {
  font-size: 0.73rem;
  color: var(--c-text-secondary);
  line-height: 1.4;
  flex: 1;
}

.buy-btn {
  width: 100%;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 5px;
  padding: 5px 8px;
  border-radius: 6px;
  border: 1px solid var(--c-border-subtle);
  background: rgba(255, 255, 255, 0.05);
  color: var(--c-text-muted);
  font-size: 0.72rem;
  font-weight: 600;
  cursor: pointer;
  transition: all 0.15s ease;
}

.buy-btn.affordable {
  background: var(--c-primary-soft);
  border-color: var(--c-primary);
  color: #ff9ec2;
}

.buy-btn.affordable:hover {
  background: var(--c-primary);
  color: #fff;
}
