
.quest-board {
  display: flex;
  flex-direction: column;
  gap: 10px;
}

.board-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  flex-wrap: wrap;
  gap: 8px;
  padding-bottom: 8px;
  border-bottom: 1px dashed var(--c-border);
}

.board-title {
  display: flex;
  align-items: center;
  gap: 6px;
  font-size: 0.86rem;
  font-weight: 700;
  color: var(--c-accent-gold);
}

.unlock-info {
  font-size: 0.74rem;
  color: var(--c-text-secondary);
}

.star-tag {
  color: var(--c-accent-gold);
  background: var(--c-accent-gold-soft);
  padding: 1px 7px;
  border-radius: 4px;
}

.quest-list {
  display: flex;
  flex-direction: column;
  gap: 10px;
}

.quest-card {
  background: var(--c-surface-card);
  border: 1px solid var(--c-border);
  border-radius: 10px;
  overflow: hidden;
}

.quest-card.status-done {
  border-color: rgba(46, 229, 157, 0.45);
  opacity: 0.88;
}

.quest-top {
  display: flex;
  align-items: center;
  justify-content: space-between;
  flex-wrap: wrap;
  gap: 8px;
  padding: 9px 12px;
  background: rgba(14, 9, 22, 0.65);
  border-bottom: 1px solid var(--c-border-subtle);
}

.quest-title-group {
  display: flex;
  align-items: center;
  gap: 8px;
  flex-wrap: wrap;
}

.quest-type-badge {
  font-size: 0.68rem;
  padding: 2px 7px;
  border-radius: 4px;
  background: var(--c-primary-soft);
  color: #ff8fb8;
  border: 1px solid var(--c-border);
  font-weight: 600;
}

.quest-name {
  font-size: 0.9rem;
  font-weight: 700;
  color: var(--c-text-primary);
}

.quest-meta-right {
  display: flex;
  align-items: center;
  gap: 8px;
  flex-wrap: wrap;
}

.quest-stars {
  display: inline-flex;
  align-items: center;
  gap: 2px;
  color: var(--c-accent-gold);
  font-size: 0.74rem;
}

.quest-stars small {
  margin-left: 4px;
  color: var(--c-text-secondary);
  font-family: var(--font-mono);
}

.quest-bounty {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  font-family: var(--font-mono);
  font-size: 0.82rem;
  font-weight: 700;
  color: var(--c-stamina-healthy);
  background: rgba(46, 229, 157, 0.14);
  padding: 2px 8px;
  border-radius: 6px;
}

.quest-status-pill {
  font-size: 0.7rem;
  font-weight: 700;
  padding: 2px 8px;
  border-radius: 999px;
}

.quest-status-pill.status-active {
  background: rgba(255, 59, 125, 0.22);
  color: #ff80ab;
  border: 1px solid var(--c-primary);
}

.quest-status-pill.status-done {
  background: rgba(46, 229, 157, 0.2);
  color: var(--c-stamina-healthy);
}

.quest-status-pill.status-failed {
  background: rgba(255, 42, 85, 0.2);
  color: var(--c-danger);
}

.quest-body {
  padding: 10px 12px;
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.quest-row {
  display: flex;
  flex-direction: column;
  gap: 3px;
  padding: 6px 9px;
  border-radius: 7px;
  background: rgba(15, 10, 22, 0.45);
}

.requirement-row {
  background: rgba(255, 59, 125, 0.08);
  border-left: 3px solid var(--c-primary);
}

.bonus-row {
  background: rgba(245, 185, 66, 0.08);
  border-left: 3px solid var(--c-accent-gold);
}

.row-label {
  display: flex;
  align-items: center;
  gap: 5px;
  font-size: 0.73rem;
  font-weight: 700;
  color: var(--c-text-muted);
}

.requirement-row .row-label {
  color: #ff8fb8;
}

.bonus-row .row-label {
  color: var(--c-accent-gold);
}

.row-content {
  font-size: 0.79rem;
  color: var(--c-text-secondary);
  line-height: 1.45;
}

.highlight-req {
  color: var(--c-text-primary);
}

.highlight-bonus {
  color: #fde68a;
}

.empty-quest {
  text-align: center;
  padding: 18px;
  color: var(--c-text-muted);
  font-size: 0.8rem;
}

.formula-tip {
  display: flex;
  align-items: center;
  gap: 7px;
  padding: 7px 10px;
  border-radius: 7px;
  background: rgba(14, 9, 20, 0.7);
  border: 1px dashed var(--c-border-subtle);
  font-size: 0.72rem;
  color: var(--c-text-muted);
  line-height: 1.4;
}

.formula-tip i {
  color: var(--c-accent-gold);
}
