
.world-header {
  padding: 10px 14px;
  background: linear-gradient(135deg, rgba(38, 20, 48, 0.96) 0%, rgba(20, 13, 28, 0.98) 100%);
  border-bottom: 1px solid var(--c-border);
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.header-top {
  display: flex;
  align-items: center;
  justify-content: space-between;
  flex-wrap: wrap;
  gap: 8px;
}

.brand-badge {
  display: flex;
  align-items: center;
  gap: 7px;
}

.brand-icon {
  color: var(--c-primary);
  font-size: 1.05rem;
  filter: drop-shadow(0 0 6px rgba(255, 59, 125, 0.6));
}

.brand-title {
  font-family: var(--font-serif);
  font-weight: 700;
  font-size: 0.98rem;
  letter-spacing: 0.08em;
  background: linear-gradient(90deg, #ff7eb3, #f5b942);
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
}

.brand-sub {
  font-family: var(--font-mono);
  font-size: 0.65rem;
  color: var(--c-text-muted);
  letter-spacing: 0.06em;
  padding-left: 4px;
  border-left: 1px solid var(--c-border);
}

.time-pill {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 3px 10px;
  border-radius: 999px;
  background: var(--c-surface-glass);
  border: 1px solid var(--c-border-subtle);
  font-size: 0.76rem;
  color: var(--c-text-secondary);
}

.time-pill i {
  color: var(--c-accent-gold);
}

.location-bar {
  display: flex;
  align-items: center;
  gap: 8px;
  flex-wrap: wrap;
  background: rgba(12, 8, 16, 0.55);
  padding: 6px 10px;
  border-radius: 8px;
  border: 1px solid var(--c-border-subtle);
}

.region-tag {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  padding: 2px 8px;
  border-radius: 5px;
  background: var(--c-primary-soft);
  border: 1px solid var(--c-border);
  color: var(--c-primary-hover);
  font-weight: 600;
  font-size: 0.76rem;
  white-space: nowrap;
}

.spot-text {
  display: flex;
  align-items: center;
  gap: 5px;
  font-size: 0.8rem;
  color: var(--c-text-primary);
  flex: 1;
  min-width: 160px;
}

.spot-pin {
  color: var(--c-accent-gold);
  font-size: 0.78rem;
}

@media (max-width: 520px) {
  .brand-sub {
    display: none;
  }
}
