
.sanniang-chamber {
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.saintess-dossier {
  background: linear-gradient(135deg, rgba(58, 18, 42, 0.85), rgba(26, 14, 34, 0.92));
  border: 1px solid var(--c-border-strong);
  border-radius: 10px;
  padding: 10px 12px;
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.dossier-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  flex-wrap: wrap;
  gap: 8px;
  padding-bottom: 7px;
  border-bottom: 1px dashed rgba(245, 185, 66, 0.35);
}

.dossier-title {
  display: flex;
  align-items: center;
  gap: 8px;
  flex-wrap: wrap;
}

.ss-badge {
  background: linear-gradient(90deg, #f5b942, #ff3b7d);
  color: #120d17;
  font-weight: 800;
  font-size: 0.7rem;
  padding: 2px 7px;
  border-radius: 5px;
}

.dossier-title h4 {
  font-family: var(--font-serif);
  font-size: 0.92rem;
  color: #ffd1e3;
}

.no-prereq-pill {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  font-size: 0.71rem;
  color: var(--c-accent-gold);
  background: var(--c-accent-gold-soft);
  padding: 2px 8px;
  border-radius: 999px;
  font-weight: 600;
}

.dossier-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(250px, 1fr));
  gap: 7px;
}

.dossier-item {
  background: rgba(14, 8, 20, 0.55);
  padding: 7px 9px;
  border-radius: 7px;
  display: flex;
  flex-direction: column;
  gap: 3px;
  font-size: 0.76rem;
}

.item-key {
  color: #ff8fb8;
  font-weight: 700;
  font-size: 0.72rem;
}

.item-val {
  color: var(--c-text-secondary);
  line-height: 1.4;
}

.highlight-mingqi {
  color: var(--c-accent-gold);
  font-weight: 600;
}

.control-section {
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.sec-head {
  display: flex;
  align-items: center;
  gap: 6px;
  font-size: 0.84rem;
  font-weight: 700;
  color: var(--c-accent-gold);
}

.forms-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 9px;
}

.form-card {
  background: var(--c-surface-card);
  border: 1px solid var(--c-border-subtle);
  border-radius: 9px;
  padding: 10px;
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  gap: 8px;
}

.form-card.active {
  border-color: var(--c-primary);
  box-shadow: 0 0 12px rgba(255, 59, 125, 0.2);
}

.form-card.materialized-card.active {
  border-color: var(--c-accent-gold);
  box-shadow: 0 0 14px rgba(245, 185, 66, 0.28);
}

.form-card-top {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 6px;
  flex-wrap: wrap;
}

.form-title {
  font-size: 0.84rem;
  font-weight: 700;
  color: var(--c-text-primary);
  display: flex;
  align-items: center;
  gap: 5px;
}

.cost-tag {
  font-family: var(--font-mono);
  font-size: 0.68rem;
  padding: 1px 6px;
  border-radius: 4px;
  font-weight: 700;
}

.cost-tag.free {
  background: rgba(46, 229, 157, 0.16);
  color: var(--c-stamina-healthy);
}

.cost-tag.spirit {
  background: var(--c-spirit-soft);
  color: #d4b8ff;
}

.cost-tag.gold {
  background: var(--c-accent-gold-soft);
  color: var(--c-accent-gold);
}

.form-desc {
  font-size: 0.74rem;
  color: var(--c-text-secondary);
  line-height: 1.42;
  flex: 1;
}

.form-action-btn {
  width: 100%;
  padding: 6px 10px;
  border-radius: 6px;
  border: 1px solid var(--c-border);
  background: var(--c-primary-soft);
  color: #ff9ec2;
  font-size: 0.74rem;
  font-weight: 700;
  cursor: pointer;
  transition: all 0.15s ease;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 5px;
}

.form-action-btn:hover:not(:disabled) {
  background: var(--c-primary);
  color: #fff;
}

.form-action-btn:disabled {
  opacity: 0.55;
  cursor: default;
}

.form-action-btn.gold-btn {
  background: linear-gradient(90deg, rgba(255, 59, 125, 0.35), rgba(245, 185, 66, 0.35));
  border-color: var(--c-border-strong);
  color: #ffe4a0;
}

.form-action-btn.gold-btn:hover {
  background: linear-gradient(90deg, #ff3b7d, #d97706);
  color: #fff;
}

.visibility-panel {
  display: flex;
  align-items: center;
  justify-content: space-between;
  flex-wrap: wrap;
  gap: 10px;
  padding: 9px 12px;
  border-radius: 8px;
  background: rgba(14, 9, 20, 0.65);
  border: 1px solid var(--c-border-subtle);
}

.vis-left {
  display: flex;
  align-items: center;
  gap: 8px;
  flex-wrap: wrap;
}

.vis-title {
  font-size: 0.76rem;
  font-weight: 700;
  color: var(--c-text-secondary);
}

.vis-options {
  display: flex;
  gap: 6px;
  flex-wrap: wrap;
}

.vis-chip {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  padding: 4px 10px;
  border-radius: 6px;
  border: 1px solid var(--c-border-subtle);
  background: var(--c-surface-card);
  color: var(--c-text-secondary);
  font-size: 0.72rem;
  font-weight: 600;
  cursor: pointer;
}

.vis-chip.active {
  border-color: var(--c-accent-gold);
  background: var(--c-accent-gold-soft);
  color: var(--c-accent-gold);
}

.hours-control {
  font-size: 0.76rem;
  color: var(--c-text-secondary);
}

.hours-control strong {
  color: var(--c-accent-gold);
  font-family: var(--font-mono);
}

@media (max-width: 680px) {
  .forms-grid {
    grid-template-columns: 1fr;
  }
}
