
.hero-stats {
  padding: 10px 14px;
  background: var(--c-surface-elevated);
  border-bottom: 1px solid var(--c-border);
  display: flex;
  flex-direction: column;
  gap: 10px;
}

.stamina-row {
  background: rgba(14, 9, 20, 0.65);
  border: 1px solid var(--c-border-subtle);
  border-radius: 9px;
  padding: 8px 11px;
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.stamina-row.is-low {
  border-color: var(--c-danger);
  background: linear-gradient(90deg, rgba(255, 42, 85, 0.14), rgba(14, 9, 20, 0.75));
}

.stamina-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  flex-wrap: wrap;
}

.stamina-label {
  display: flex;
  align-items: center;
  gap: 6px;
  font-size: 0.82rem;
  font-weight: 600;
}

.stamina-icon {
  color: var(--c-stamina-healthy);
}

.stamina-status-tag {
  font-size: 0.7rem;
  padding: 1px 7px;
  border-radius: 999px;
  font-weight: 600;
}

.stamina-status-tag.state-healthy {
  background: rgba(46, 229, 157, 0.16);
  color: var(--c-stamina-healthy);
  border: 1px solid rgba(46, 229, 157, 0.4);
}

.stamina-status-tag.state-warn {
  background: rgba(245, 158, 11, 0.18);
  color: var(--c-stamina-warning);
  border: 1px solid rgba(245, 158, 11, 0.45);
}

.stamina-status-tag.state-danger,
.stamina-status-tag.state-empty {
  background: var(--c-danger-soft);
  color: var(--c-danger);
  border: 1px solid var(--c-danger);
}

.stamina-right {
  display: flex;
  align-items: center;
  gap: 8px;
}

.stamina-numbers {
  font-family: var(--font-mono);
  font-size: 0.86rem;
}

.stamina-numbers strong {
  color: var(--c-text-primary);
}

.stamina-numbers small {
  color: var(--c-text-muted);
  margin-left: 2px;
}

.stamina-controls {
  display: flex;
  gap: 4px;
}

.mini-btn {
  padding: 2px 6px;
  font-size: 0.7rem;
  font-family: var(--font-mono);
  border-radius: 4px;
  border: 1px solid var(--c-border);
  background: var(--c-surface-card);
  color: var(--c-text-secondary);
  cursor: pointer;
  transition: all 0.15s ease;
}

.mini-btn:hover:not(:disabled) {
  background: var(--c-primary-soft);
  color: var(--c-text-primary);
  border-color: var(--c-primary);
}

.mini-btn:disabled {
  opacity: 0.4;
  cursor: not-allowed;
}

.stamina-track {
  width: 100%;
  height: 8px;
  background: rgba(255, 255, 255, 0.07);
  border-radius: 999px;
  overflow: hidden;
}

.stamina-fill {
  height: 100%;
  border-radius: 999px;
  transition: width 0.3s ease;
}

.stamina-fill.state-healthy {
  background: linear-gradient(90deg, #10b981, #2ee59d);
}

.stamina-fill.state-warn {
  background: linear-gradient(90deg, #d97706, #fbbf24);
}

.stamina-fill.state-danger,
.stamina-fill.state-empty {
  background: linear-gradient(90deg, #be123c, #ff2a55);
}

.stamina-warning {
  display: flex;
  align-items: center;
  gap: 6px;
  font-size: 0.74rem;
  color: #ff809b;
  padding-top: 2px;
}

.currency-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 8px;
}

.stat-pill {
  display: flex;
  align-items: center;
  gap: 9px;
  padding: 8px 10px;
  border-radius: 9px;
  background: var(--c-surface-card);
  border: 1px solid var(--c-border-subtle);
}

.hehuan-pill {
  border-color: rgba(255, 59, 125, 0.35);
}

.money-pill {
  border-color: rgba(245, 185, 66, 0.35);
}

.score-pill {
  border-color: rgba(181, 137, 255, 0.35);
}

.pill-icon {
  width: 32px;
  height: 32px;
  border-radius: 8px;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 0.95rem;
  flex-shrink: 0;
}

.hehuan-pill .pill-icon {
  background: var(--c-primary-soft);
  color: var(--c-primary);
}

.money-pill .pill-icon {
  background: var(--c-accent-gold-soft);
  color: var(--c-accent-gold);
}

.score-pill .pill-icon {
  background: var(--c-spirit-soft);
  color: var(--c-spirit);
}

.pill-body {
  display: flex;
  flex-direction: column;
  gap: 2px;
  min-width: 0;
  flex: 1;
}

.pill-label {
  font-size: 0.7rem;
  color: var(--c-text-muted);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.pill-value-row {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 6px;
  flex-wrap: wrap;
}

.pill-value {
  font-family: var(--font-mono);
  font-size: 0.95rem;
  font-weight: 700;
}

.hehuan-pill .pill-value {
  color: #ff6b9d;
}

.money-pill .pill-value {
  color: var(--c-accent-gold);
}

.score-pill .pill-value {
  color: #d0b3ff;
}

.pill-hint {
  font-size: 0.66rem;
  color: var(--c-text-muted);
}

.star-unlock-badge {
  display: inline-flex;
  align-items: center;
  gap: 3px;
  font-size: 0.68rem;
  padding: 1px 6px;
  border-radius: 4px;
  background: var(--c-accent-gold-soft);
  color: var(--c-accent-gold);
  font-weight: 600;
}

@media (max-width: 640px) {
  .currency-grid {
    grid-template-columns: 1fr;
  }
}
