
.sanniang-banner {
  padding: 11px 14px;
  background: linear-gradient(135deg, rgba(45, 22, 54, 0.92), rgba(25, 15, 34, 0.95));
  border-bottom: 1px solid var(--c-border);
  display: flex;
  flex-direction: column;
  gap: 8px;
  transition: all 0.25s ease;
}

.sanniang-banner.form-materialized {
  background: linear-gradient(135deg, rgba(72, 20, 48, 0.95), rgba(38, 16, 40, 0.96));
  border-bottom: 1px solid var(--c-border-strong);
  box-shadow: inset 0 0 18px rgba(255, 59, 125, 0.18);
}

.sanniang-banner.form-haunting {
  background: linear-gradient(135deg, rgba(42, 24, 68, 0.94), rgba(24, 16, 40, 0.96));
}

.banner-top {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
  flex-wrap: wrap;
}

.persona-left {
  display: flex;
  align-items: center;
  gap: 10px;
}

.avatar-medallion {
  position: relative;
  width: 38px;
  height: 38px;
  border-radius: 50%;
  background: radial-gradient(circle at 30% 30%, #ff6b9d, #8a1548);
  border: 1.5px solid var(--c-accent-gold);
  display: flex;
  align-items: center;
  justify-content: center;
  color: #fff;
  font-size: 1rem;
  flex-shrink: 0;
  box-shadow: 0 0 10px rgba(255, 59, 125, 0.4);
}

.ss-tag {
  position: absolute;
  bottom: -3px;
  right: -4px;
  background: linear-gradient(90deg, #f5b942, #ff3b7d);
  color: #120d17;
  font-family: var(--font-mono);
  font-weight: 800;
  font-size: 0.6rem;
  padding: 0 4px;
  border-radius: 4px;
  border: 1px solid #fff;
}

.persona-meta {
  display: flex;
  flex-direction: column;
  gap: 3px;
}

.name-line {
  display: flex;
  align-items: baseline;
  gap: 7px;
  flex-wrap: wrap;
}

.persona-name {
  font-family: var(--font-serif);
  font-size: 0.96rem;
  font-weight: 700;
  color: #ff8fb8;
}

.persona-title {
  font-size: 0.72rem;
  color: var(--c-text-muted);
}

.form-badges {
  display: flex;
  align-items: center;
  gap: 6px;
  flex-wrap: wrap;
}

.form-pill,
.timer-pill,
.vis-pill {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  font-size: 0.7rem;
  padding: 1px 8px;
  border-radius: 999px;
  font-weight: 600;
}

.form-pill.form-spirit {
  background: var(--c-primary-soft);
  color: #ff8fb8;
  border: 1px solid var(--c-border);
}

.form-pill.form-haunting {
  background: var(--c-spirit-soft);
  color: #d4b8ff;
  border: 1px solid rgba(181, 137, 255, 0.45);
}

.form-pill.form-materialized {
  background: linear-gradient(90deg, rgba(245, 185, 66, 0.25), rgba(255, 59, 125, 0.3));
  color: var(--c-accent-gold);
  border: 1px solid var(--c-border-strong);
}

.timer-pill {
  background: rgba(245, 185, 66, 0.16);
  color: var(--c-accent-gold);
  border: 1px solid rgba(245, 185, 66, 0.4);
}

.vis-pill {
  background: rgba(255, 255, 255, 0.08);
  color: var(--c-text-secondary);
  border: 1px solid var(--c-border-subtle);
}

.vis-pill.is-public {
  background: rgba(46, 229, 157, 0.16);
  color: var(--c-stamina-healthy);
  border-color: rgba(46, 229, 157, 0.4);
}

.quick-actions {
  display: flex;
  align-items: center;
  gap: 6px;
  flex-wrap: wrap;
}

.action-btn {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  padding: 5px 10px;
  border-radius: 7px;
  font-size: 0.73rem;
  font-weight: 600;
  cursor: pointer;
  transition: all 0.18s ease;
  font-family: inherit;
}

.materialize-btn {
  background: rgba(255, 59, 125, 0.15);
  border: 1px solid var(--c-border);
  color: #ff9ec2;
}

.materialize-btn.can-afford {
  background: linear-gradient(90deg, #ff3b7d, #d97706);
  border-color: var(--c-accent-gold);
  color: #fff;
  box-shadow: 0 0 10px rgba(255, 59, 125, 0.38);
}

.materialize-btn:hover {
  transform: translateY(-1px);
  border-color: var(--c-accent-gold);
}

.vis-toggle-btn {
  background: var(--c-surface-card);
  border: 1px solid var(--c-border-strong);
  color: var(--c-accent-gold);
}

.vis-toggle-btn:hover {
  background: var(--c-accent-gold-soft);
}

.quote-bubble {
  position: relative;
  background: rgba(14, 8, 20, 0.62);
  border-left: 3px solid var(--c-primary);
  border-radius: 4px 8px 8px 4px;
  padding: 7px 11px 7px 26px;
}

.quote-mark {
  position: absolute;
  left: 8px;
  top: 8px;
  font-size: 0.75rem;
  color: var(--c-primary);
  opacity: 0.75;
}

.quote-text {
  font-size: 0.81rem;
  color: var(--c-text-primary);
  line-height: 1.45;
}

.arousal-strip {
  display: flex;
  align-items: flex-start;
  gap: 8px;
  font-size: 0.75rem;
  color: var(--c-text-secondary);
  background: rgba(255, 59, 125, 0.07);
  padding: 5px 9px;
  border-radius: 6px;
  border: 1px dashed rgba(255, 94, 148, 0.25);
}

.arousal-badge {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  color: #ff7aa8;
  font-weight: 600;
  white-space: nowrap;
  flex-shrink: 0;
}

.arousal-desc {
  line-height: 1.4;
}
