
.prey-codex {
  display: flex;
  flex-direction: column;
  gap: 10px;
}

.codex-toolbar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  flex-wrap: wrap;
  gap: 8px;
  padding-bottom: 8px;
  border-bottom: 1px dashed var(--c-border);
}

.toolbar-title {
  display: flex;
  align-items: center;
  gap: 6px;
  font-size: 0.86rem;
  font-weight: 700;
  color: #ff8fb8;
}

.tier-filters {
  display: flex;
  align-items: center;
  gap: 5px;
  flex-wrap: wrap;
}

.filter-chip {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  padding: 3px 8px;
  border-radius: 6px;
  border: 1px solid var(--c-border-subtle);
  background: var(--c-surface-card);
  color: var(--c-text-secondary);
  font-size: 0.72rem;
  font-weight: 600;
  cursor: pointer;
  transition: all 0.15s ease;
}

.filter-chip.active {
  border-color: var(--c-primary);
  background: var(--c-primary-soft);
  color: #fff;
}

.chip-count {
  font-family: var(--font-mono);
  font-size: 0.66rem;
  opacity: 0.8;
}

.prey-grid {
  display: flex;
  flex-direction: column;
  gap: 10px;
}

.prey-card {
  background: var(--c-surface-card);
  border: 1px solid var(--c-border-subtle);
  border-radius: 10px;
  overflow: hidden;
  transition: border-color 0.2s ease;
}

.prey-card.tier-s {
  border-color: rgba(245, 185, 66, 0.55);
  box-shadow: 0 0 12px rgba(245, 185, 66, 0.12);
}

.prey-card.tier-a {
  border-color: rgba(255, 59, 125, 0.45);
}

.prey-card.tier-b {
  border-color: rgba(181, 137, 255, 0.35);
}

.prey-card-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
  padding: 9px 12px;
  background: rgba(15, 10, 22, 0.55);
  border-bottom: 1px solid var(--c-border-subtle);
  cursor: pointer;
}

.head-left {
  display: flex;
  align-items: center;
  gap: 10px;
}

.tier-medal {
  width: 34px;
  height: 34px;
  border-radius: 8px;
  display: flex;
  align-items: center;
  justify-content: center;
  font-family: var(--font-mono);
  font-size: 1rem;
  font-weight: 800;
  flex-shrink: 0;
}

.tier-medal.tier-s {
  background: linear-gradient(135deg, #f5b942, #ff3b7d);
  color: #120d17;
  box-shadow: 0 0 10px rgba(245, 185, 66, 0.45);
}

.tier-medal.tier-a {
  background: linear-gradient(135deg, #ff3b7d, #9d174d);
  color: #fff;
}

.tier-medal.tier-b {
  background: linear-gradient(135deg, #a78bfa, #5b21b6);
  color: #fff;
}

.tier-medal.tier-c {
  background: rgba(255, 255, 255, 0.14);
  color: var(--c-text-secondary);
}

.name-block {
  display: flex;
  flex-direction: column;
  gap: 2px;
}

.name-row {
  display: flex;
  align-items: center;
  gap: 7px;
  flex-wrap: wrap;
}

.prey-name {
  font-size: 0.92rem;
  font-weight: 700;
  color: var(--c-text-primary);
}

.prey-rating-full {
  font-size: 0.7rem;
  padding: 1px 6px;
  border-radius: 4px;
  background: rgba(255, 59, 125, 0.15);
  color: #ff8fb8;
  font-weight: 600;
}

.prey-sub {
  font-size: 0.73rem;
  color: var(--c-text-muted);
}

.expand-toggle {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  padding: 4px 9px;
  border-radius: 6px;
  border: 1px solid var(--c-border);
  background: rgba(255, 59, 125, 0.1);
  color: #ff9ec2;
  font-size: 0.72rem;
  font-weight: 600;
  cursor: pointer;
}

.expand-toggle i {
  transition: transform 0.2s ease;
}

.expand-toggle i.rotated {
  transform: rotate(180deg);
}

.prey-summary {
  padding: 9px 12px;
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.summary-line {
  display: flex;
  align-items: flex-start;
  gap: 8px;
  font-size: 0.78rem;
  line-height: 1.4;
}

.field-tag {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  color: var(--c-text-muted);
  font-weight: 600;
  white-space: nowrap;
  min-width: 72px;
}

.field-val {
  color: var(--c-text-secondary);
  flex: 1;
}

.mingqi-line .mingqi-val {
  color: #c4b5fd;
}

.mingqi-line.is-identified .mingqi-val {
  color: var(--c-accent-gold);
  font-weight: 600;
}

.status-highlight {
  color: #ff9ec2;
}

.prey-micro-details {
  padding: 10px 12px;
  background: rgba(12, 8, 18, 0.65);
  border-top: 1px dashed var(--c-border);
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.micro-item {
  display: flex;
  flex-direction: column;
  gap: 3px;
}

.micro-label {
  display: flex;
  align-items: center;
  gap: 5px;
  font-size: 0.74rem;
  font-weight: 700;
  color: var(--c-accent-gold);
}

.micro-text {
  font-size: 0.77rem;
  color: var(--c-text-secondary);
  line-height: 1.45;
  padding-left: 18px;
}

.empty-box {
  text-align: center;
  padding: 20px;
  color: var(--c-text-muted);
  font-size: 0.82rem;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 6px;
}
